INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',7,'Ivy','Got it. Will I have time for lunch?','艾薇：明白。我还来得及吃午饭吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',8,'Agent','Sure. Boarding will start at 3:15. You have two hours.','值机员：来得及。3 点 15 分开始登机，您还有两小时。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',9,'Ivy','Perfect. One more thing—which way is the food court?','艾薇：太好了。还有一件事——美食广场往哪边走？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',10,'Agent','Go straight, past Gate 8. You''ll see it on the left.','值机员：直走，过 8 号登机口，左手边就能看到。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
